background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    border: 1px solid #e1e5e9;
}

.key-creation h2, .key-validation h2, .created-keys h2

.keys-manager {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    line-height: 1.6;
}

.keys-header {
    text-align: center;
    margin-bottom: 3rem;
    padding: 2rem;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

.keys-header h1 {
    margin: 0 0 0.5rem 0;
    font-size: 2.5rem;
    font-weight: 700;
}

.keys-header p {
    margin: 0;
    font-size: 1.1rem;
    opacity: 0.9;
}

.keys-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
    margin-bottom: 2rem;
}

.key-creation, .key-validation {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    border: 1px solid #e1e5e9;
}

.created-keys {
    grid-column: span 2;
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    border: 1px solid #e1e5e9;
}

.key-creation h2, .key-validation h2, .created-keys h2 {
    margin: 0 0 1.5rem 0;
    color: #2d3748;
    font-size: 1.5rem;
    font-weight: 600;
    border-bottom: 2px solid #edf2f7;
    padding-bottom: 0.5rem;
}

/* Form Styles */
.key-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.form-group label {
    font-weight: 600;
    color: #4a5568;
    font-size: 0.9rem;
}

.form-group input, .form-group textarea {
    padding: 0.75rem;
    border: 2px solid #e2e8f0;
    border-radius: 8px;
    font-size: 1rem;
    transition: all 0.2s ease;
    background: #fafafa;
}

.form-group input:focus, .form-group textarea:focus {
    outline: none;
    border-color: #667eea;
    background: white;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.form-group small {
    color: #718096;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

/* Button Styles */
.btn-primary, .btn-secondary {
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.btn-primary {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(102, 126, 234, 0.3);
}

.btn-secondary {
    background: #f7fafc;
    color: #4a5568;
    border: 2px solid #e2e8f0;
}

.btn-secondary:hover {
    background: #edf2f7;
    border-color: #cbd5e0;
}

/* Validation Styles */
.validation-form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.validation-result {
    margin-top: 1rem;
}

.validation-success, .validation-error {
    padding: 1.5rem;
    border-radius: 8px;
    margin-top: 1rem;
}

.validation-success {
    background: #f0fff4;
    border: 2px solid #9ae6b4;
    color: #22543d;
}

.validation-error {
    background: #fed7d7;
    border: 2px solid #fc8181;
    color: #742a2a;
}

.validation-success h3, .validation-error h3 {
    margin: 0 0 1rem 0;
    font-size: 1.1rem;
}

.key-details p {
    margin: 0.5rem 0;
    font-size: 0.9rem;
}

.expired-details {
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px solid rgba(116, 42, 42, 0.2);
}

/* Keys List Styles */
.keys-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.no-keys {
    text-align: center;
    color: #718096;
    font-style: italic;
    padding: 2rem;
}

.key-item {
    border: 2px solid #e2e8f0;
    border-radius: 12px;
    padding: 1.5rem;
    transition: all 0.2s ease;
    background: #fafafa;
}

.key-item:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
}

.key-item.valid {
    border-color: #9ae6b4;
    background: #f0fff4;
}

.key-item.expired {
    border-color: #fc8181;
    background: #fed7d7;
    opacity: 0.7;
}

.key-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 1rem;
    gap: 1rem;
}

.key-actions {
    display: flex;
    gap: 0.5rem;
}

.key-status {
    font-size: 1.2rem;
}

.key-string {
    font-weight: 600;
    color: #2d3748;
    flex: 1;
    font-family: 'Courier New', monospace;
}

.copy-btn, .delete-btn {
    padding: 0.5rem 1rem;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.8rem;
    transition: all 0.2s ease;
}

.copy-btn {
    background: #667eea;
}

.copy-btn:hover {
    background: #764ba2;
    transform: scale(1.05);
}

.delete-btn {
    background: #f56565;
}

.delete-btn:hover {
    background: #e53e3e;
    transform: scale(1.05);
}

.key-details {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.key-info {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
    font-size: 0.85rem;
    color: #4a5568;
}

.key-info span {
    background: white;
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    border: 1px solid #e2e8f0;
}

.key-value {
    background: #2d3748;
    padding: 1rem;
    border-radius: 8px;
    overflow-x: auto;
}

.key-value code {
    color: #a0aec0;
    font-family: 'Courier New', monospace;
    font-size: 0.9rem;
    word-break: break-all;
    white-space: pre-wrap;
}

#keys-count {
    color: #667eea;
    font-weight: 600;
}

/* Toast Notifications */
.toast {
    position: fixed;
    top: 2rem;
    right: 2rem;
    padding: 1rem 1.5rem;
    border-radius: 8px;
    color: white;
    font-weight: 600;
    z-index: 1000;
    transform: translateX(100%);
    transition: transform 0.3s ease;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.2);
}

.toast.show {
    transform: translateX(0);
}

.toast-success {
    background: linear-gradient(135deg, #48bb78 0%, #38a169 100%);
}

.toast-error {
    background: linear-gradient(135deg, #f56565 0%, #e53e3e 100%);
}

/* Responsive Design */
@media (max-width: 768px) {
    .keys-manager {
        padding: 1rem;
    }
    
    .keys-content {
        grid-template-columns: 1fr;
    }
    
    .created-keys {
        grid-column: span 1;
    }
    
    .keys-header h1 {
        font-size: 2rem;
    }
    
    .form-actions {
        flex-direction: column;
    }
    
    .key-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 0.5rem;
    }
    
    .key-info {
        flex-direction: column;
        gap: 0.5rem;
    }
    
    .toast {
        top: 1rem;
        right: 1rem;
        left: 1rem;
        transform: translateY(-100%);
    }
    
    .toast.show {
        transform: translateY(0);
    }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
    .keys-manager {
        background: #1a202c;
        color: #e2e8f0;
    }
    
    .key-creation, .key-validation, .created-keys {
        background: #2d3748;
        border-color: #4a5568;
        color: #e2e8f0;
    }
    
    .form-group input, .form-group textarea {
        background: #1a202c;
        border-color: #4a5568;
        color: #e2e8f0;
    }
    
    .form-group input:focus, .form-group textarea:focus {
        background: #2d3748;
    }
    
    .key-item {
        background: #1a202c;
        border-color: #4a5568;
    }
    
    .key-info span {
        background: #2d3748;
        border-color: #4a5568;
    }
    
    .key-value {
        background: #0d1117;
    }
}

